program.source:
Subroutine Suspendable Doble(numero As Integer) As Integer
  Return numero * 2;
EndSubroutine

Subroutine Suspendable Triple(numero As Integer) As Integer
  Return numero * 3;
EndSubroutine

Algorithm DobleYTriple
  Define numero As Integer;
  Read numero;
  Tasks
    Define doble As Task<Integer> <- Spawn Doble(numero);
    Define triple As Task<Integer> <- Spawn Triple(numero);
    Define parteTriple As Integer <- 0;
    Write Await doble + parteTriple;
    parteTriple <- Await triple;
  EndTasks
EndAlgorithm

